/* Pueo feature marks, 200x200, shown for a beat when Hunt and Spotter open.
 *
 * Sources are art/pueo_hunt_src.png and art/pueo_spotter_src.jpg, which are
 * in the repository and not in the source archive -- same as the owl, and
 * for the same reason: they only buy the ability to regenerate what is
 * already sitting here. Regenerate with
 *
 *   tools/make_bitmap.py art/pueo_hunt_src.png --name pueo_hunt  *       --size 200x200 --fit --invert --crop
 *
 * --invert because the artwork is black on white and drawBitmap paints the
 * set bits: without it the owl is the clear bits and the screen looks dead.
 *
 * 200 is where the detail survives one-bit. At 160 the radio mast on the
 * Spotter mark collapses into a smear and the arcs on the Hunt mark start
 * merging; both were checked by converting and looking, not by guessing.
 * Neither carries a frame -- a baked-in border is the first thing to go
 * thin, and the UI can draw one with drawRect if it ever wants one. */
